package com.digitalhealth.service;
import com.digitalhealth.dto.AppointmentDTO; import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class AppointmentService { private final AppointmentRepository appointments; private final WorkerRepository workers; private final HealthcareCenterRepository centers; private final NotificationService notifications; public AppointmentService(AppointmentRepository a,WorkerRepository w,HealthcareCenterRepository c,NotificationService n){appointments=a;workers=w;centers=c;notifications=n;} public AppointmentDTO book(Long workerId,AppointmentDTO d){Worker w=workers.findById(workerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Worker not found"));if(appointments.existsByWorkerIdAndProviderAndAppointmentAt(workerId,d.getProvider(),d.getAppointmentAt()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Duplicate appointment");Appointment a=new Appointment();a.setWorker(w);a.setProvider(d.getProvider());a.setAppointmentAt(d.getAppointmentAt());a.setReason(d.getReason());a.setNotes(d.getNotes());if(d.getCenterId()!=null)a.setCenter(centers.findById(d.getCenterId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Healthcare center not found")));a=appointments.save(a);notifications.create(w,"Appointment booked for "+d.getAppointmentAt(),"APPOINTMENT");return dto(a);} public List<AppointmentDTO> list(Long workerId){return appointments.findByWorkerIdOrderByAppointmentAtDesc(workerId).stream().map(this::dto).toList();} public AppointmentDTO status(Long workerId,Long id,String status){if(!Set.of("PENDING","CONFIRMED","COMPLETED","CANCELLED","REJECTED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid appointment status");Appointment a=appointments.findById(id).filter(x->x.getWorker().getId().equals(workerId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));a.setStatus(status);a=appointments.save(a);notifications.create(a.getWorker(),"Appointment status changed to "+status,"APPOINTMENT");return dto(a);} private AppointmentDTO dto(Appointment a){AppointmentDTO d=new AppointmentDTO();d.setId(a.getId());d.setProvider(a.getProvider());d.setAppointmentAt(a.getAppointmentAt());d.setReason(a.getReason());d.setNotes(a.getNotes());d.setStatus(a.getStatus());if(a.getCenter()!=null)d.setCenterId(a.getCenter().getId());return d;} }
